// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }

    function testFuzz_property(uint256 blocknum, uint256 timestamp, address sender) public {
        vm.assume(blocknum > 0);
        vm.assume(timestamp > 0);
        vm.assume(sender != address(0));
        vm.assume(sender != address(this));
        vm.assume(sender != address(c));

        vm.deal(sender, 10 ether);

        vm.roll(blocknum);
        vm.warp(timestamp);

        vm.prank(sender);
        (bool ok,) = address(c).call{value: 10 ether}("");
        require(ok, "call should succeed");

        if (blocknum % 15 == 0) {
            assertEq(address(c).balance, 0, "balance should be transferred");
        } else {
            assertEq(address(c).balance, 10 ether, "balance should remain");
        }
    }
}
